/* Rotation follows the world's scroll position through the planet-to-ocean cut.
   There is no upper clamp at the end of the globe chapter and no time-based spin. */
export function globeScrollDegrees(y, globalStart, globalHeight, degreesPerSection = 34) {
  if (![y, globalStart, globalHeight].every(Number.isFinite)) return 0;
  const span = Math.max(1, globalHeight);
  const progress = Math.max(0, (y - globalStart) / span);
  return progress * (Number.isFinite(degreesPerSection) ? degreesPerSection : 34);
}
